(function(){
  function parsePath(path){
    var cleaned=String(path||'').replace(/^\./,'');
    var parts=[], buf='', i=0;
    while(i<cleaned.length){
      var c=cleaned[i];
      if(c==='.'){ if(buf){parts.push(buf);} buf=''; i++; }
      else if(c==='['){
        if(buf){parts.push(buf);buf='';}
        var j=cleaned.indexOf(']',i); if(j<0){parts.push(cleaned.slice(i));break;}
        parts.push(cleaned.slice(i,j+1)); i=j+1;
      } else { buf+=c; i++; }
    }
    if(buf) parts.push(buf);
    return parts;
  }
  function walk(obj, parts){
    var cur=obj;
    for(var i=0;i<parts.length;i++){
      var p=parts[i]; if(p==='') continue;
      var idx=p.match(/^\[(\d+)\]$/);
      if(idx){ cur=cur[parseInt(idx[1],10)]; }
      else { cur=cur[p]; }
      if(cur===undefined) return {error:'路径不存在: '+parts.slice(0,i+1).join('.')};
    }
    return {value: cur};
  }
  function select(data, path){
    var obj;
    try{ obj=JSON.parse(data); }catch(e){ return {error:'JSON 解析失败: '+e.message}; }
    var r=walk(obj, parsePath(path));
    if(r.error) return r;
    return {value: JSON.stringify(r.value, null, 2)};
  }
  var API={select:select, parsePath:parsePath, walk:walk};
  if(typeof module!=='undefined'&&module.exports)module.exports=API;
  if(typeof window!=='undefined')window.__DaselForge__=API;
})();
